{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/faq-help.json
    The help card beside the questions of FaqSplit: a title, a line of text, the ways to reach the team (icon, name, one line) and a link.
    Props (p): labels, channels, landmarkLabel. *}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_channels = ($p['channels'] ?? null)}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_11}
  {capture $c_3}
    {capture $c_1}
      {=ui_text(ui_get($v_labels, ['asideTitle']))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'lg', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
    {capture $c_2}
      {=ui_text(ui_get($v_labels, ['asideText']))}
    {/capture}
    {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
  {/capture}
  {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_3])|noescape}
  {capture $c_9}
    {foreach ui_l($v_channels) as $v_c}
      {capture $c_8}
        {capture $c_4}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_c, ['icon'])), 'Size' => 20]])|noescape}
        {/capture}
        {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex size-10 shrink-0 items-center justify-center rounded bg-muted'], 'children' => $c_4])|noescape}
        {capture $c_7}
          {capture $c_5}
            {=ui_text(ui_get($v_c, ['title']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_5])|noescape}
          {capture $c_6}
            {=ui_text(ui_get($v_c, ['text']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_6])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0'], 'children' => $c_7])|noescape}
      {/capture}
      {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => 'flex items-start gap-4', 'Attrs' => ui_attrs(['data-testid', 'faq-channel'])], 'children' => $c_8])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none flex-col gap-4 p-0'], 'children' => $c_9])|noescape}
  {capture $c_10}
    {=ui_text(ui_get($v_labels, ['asideCta']))}
    {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'arrow-right', 'Size' => 16]])|noescape}
  {/capture}
  {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/contact', 'Variant' => 'default', 'Size' => 'sm', 'Class' => 'font-medium'], 'children' => $c_10])|noescape}
{/capture}
{=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'aside', 'Class' => 'rounded bg-card inset-ring inset-ring-border flex flex-col gap-6 p-6', 'Attrs' => ui_attrs(['aria-label', ui_coalesce([$v_landmarkLabel, ui_get($v_labels, ['asideTitle'])]), 'data-testid', 'faq-help'])], 'children' => $c_11])|noescape}
